const clip_t *clips_get(clip_id_t id)
{
    if (id <= CLIP_NONE || id >= CLIP_COUNT) {
        return NULL;
    }
    return &CLIPS[id];
}

static const float SCALE[CLIP_FIELDS] = {1.0f / 16, 1.0f / 16, 1.0f / 4096, 1.0f / 4096, 1.0f / 16, 1.0f / 4096, 1.0f / 16, 1.0f / 16, 1.0f / 4096, 1.0f / 16, 1.0f / 16, 1.0f / 4096, 1.0f / 4096, 1.0f / 16, 1.0f / 16, 1.0f / 4096, 1.0f / 16, 1.0f / 4096, 1.0f / 4096, 1.0f / 4096, 1.0f / 4096, 1.0f / 4096, 1.0f / 16, 1.0f / 4096, 1.0f / 4096, 1.0f / 4096, 1.0f / 4096, 1.0f / 4096, 1.0f / 16, 1.0f / 16, 1.0f / 4096, 1.0f / 4096, 1.0f / 4096};

void clips_frame(const clip_t *clip, int i, clip_frame_t *out)
{
    float *o = (float *) out;
    for (int j = 0; j < CLIP_FIELDS; j++) {
        o[j] = (float) clip->frames[i].v[j] * SCALE[j];
    }
}

clip_id_t clips_find(const char *name)
{
    for (int i = CLIP_NONE + 1; i < CLIP_COUNT; i++) {
        if (name != NULL && strcmp(name, CLIPS[i].name) == 0) {
            return (clip_id_t) i;
        }
    }
    return CLIP_NONE;
}
